package com.jingyue;

import org.springframework.web.bind.annotation.*;
import org.springframework.data.redis.core.script.RedisScript;
import org.redisson.api.*;
import java.util.*;
import java.time.*;
import java.sql.PreparedStatement;
import java.sql.Statement;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import static com.jingyue.Values.*;

@RestController
@RequestMapping("/api/v1/admin")
public class AdminController {
    final Db db;final RedisOps ops;final TicketWriter writer;final TicketPipeline pipeline;final RedissonClient redisson;
    final RedisScript<Long> warmup=RedisOps.script("warmup.lua",Long.class);
    public AdminController(Db db,RedisOps ops,TicketWriter writer,TicketPipeline pipeline,RedissonClient redisson){this.db=db;this.ops=ops;this.writer=writer;this.pipeline=pipeline;this.redisson=redisson;}
    long inserted(String sql,Object... args){GeneratedKeyHolder h=new GeneratedKeyHolder();db.jdbc.update(c->{PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)s.setObject(i+1,args[i]);return s;},h);return h.getKey().longValue();}
    @GetMapping("/attractions") public Object attractions(){Identity.role("ADMIN");return map("items",stringIds(db.rows("SELECT s.*,p.* FROM tb_shop s JOIN tb_attraction_profile p ON p.shop_id=s.id ORDER BY s.id")));}
    @PostMapping("/attractions") public Object attraction(@RequestBody Map<String,Object> b){Identity.role("ADMIN");String name=required(b,"name",100),city=required(b,"cityName",40),category=required(b,"category",40),address=required(b,"address",255),intro=required(b,"introduction",20000),notice=required(b,"admissionNotice",10000),image=image(b);
        long actor=Identity.id();return db.tx(()->{long id=inserted("INSERT INTO tb_shop(name,type_id,address,x,y,images,open_hours) VALUES(?,1,?,0,0,?,?)",name,address,image,required(b,"openHours",100));db.update("INSERT INTO tb_attraction_profile(shop_id,city_code,city_name,category,introduction,admission_notice,published) VALUES(?,?,?,?,?,?,?)",id,required(b,"cityCode",20),city,category,intro,notice,Boolean.TRUE.equals(b.get("published"))?1:0);db.audit(actor,"CREATE_ATTRACTION",Long.toString(id),"","CREATED");return map("attractionId",Long.toString(id));});}
    static String image(Map<String,Object> b){String s=required(b,"image",255);if(!s.matches("/assets/(valley|town|coast|gallery)\\.webp"))throw new ApiFault(400,"INVALID_IMAGE","请选择项目内景点素材");return s;}
    @PutMapping("/attractions/{id}") public Object editAttraction(@PathVariable long id,@RequestBody Map<String,Object> b){Identity.role("ADMIN");long actor=Identity.id();return db.tx(()->{Map<String,Object> p=db.need("SELECT * FROM tb_attraction_profile WHERE shop_id=? FOR UPDATE",id);long v=number(p,"content_version")+1;db.update("UPDATE tb_shop SET name=?,address=?,open_hours=?,images=? WHERE id=?",required(b,"name",100),required(b,"address",255),required(b,"openHours",100),image(b),id);db.update("UPDATE tb_attraction_profile SET introduction=?,admission_notice=?,published=?,content_version=?,city_code=?,city_name=?,category=? WHERE shop_id=?",required(b,"introduction",20000),required(b,"admissionNotice",10000),Boolean.TRUE.equals(b.get("published"))?1:0,v,b.containsKey("cityCode")?required(b,"cityCode",20):p.get("city_code"),b.containsKey("cityName")?required(b,"cityName",40):p.get("city_name"),b.containsKey("category")?required(b,"category",40):p.get("category"),id);writer.outbox("cache:"+id+":"+v,Long.toString(id),"CACHE",map("attractionId",Long.toString(id),"version",v));
        if(!Boolean.TRUE.equals(b.get("published"))) {for(Map<String,Object> s:db.rows("SELECT s.id FROM tb_ticket_sku s JOIN tb_ticket_product p ON p.id=s.product_id WHERE p.attraction_id=? AND s.state='ON_SALE'",id)){db.update("UPDATE tb_ticket_sku SET control_state='PAUSING' WHERE id=?",s.get("id"));writer.outbox("pause:"+s.get("id")+":"+UUID.randomUUID(),text(s,"id"),"PAUSE",map("skuId",text(s,"id")));}}
        db.audit(actor,"EDIT_ATTRACTION",Long.toString(id),text(p,"content_version"),Long.toString(v));return map("contentVersion",Long.toString(v));});}
    @GetMapping("/ticket-products") public Object products(){Identity.role("ADMIN");return map("items",stringIds(db.rows("SELECT p.*,s.name AS attraction_name FROM tb_ticket_product p JOIN tb_shop s ON s.id=p.attraction_id ORDER BY p.id")));}
    @PostMapping("/ticket-products") public Object product(@RequestBody Map<String,Object> b){Identity.role("ADMIN");long attraction=positive(b,"attractionId"),actor=Identity.id();return db.tx(()->{db.need("SELECT id FROM tb_shop WHERE id=?",attraction);long id=inserted("INSERT INTO tb_ticket_product(attraction_id,name,description) VALUES(?,?,?)",attraction,required(b,"name",100),required(b,"description",10000));invalidateAttraction(attraction);db.audit(actor,"CREATE_PRODUCT",Long.toString(id),"","ACTIVE");return map("productId",Long.toString(id));});}
    void invalidateAttraction(long id){db.update("UPDATE tb_attraction_profile SET content_version=content_version+1 WHERE shop_id=?",id);long v=db.count("SELECT content_version FROM tb_attraction_profile WHERE shop_id=?",id);writer.outbox("cache:"+id+":"+v,Long.toString(id),"CACHE",map("attractionId",Long.toString(id),"version",v));}
    @PutMapping("/ticket-products/{id}") public Object editProduct(@PathVariable long id,@RequestBody Map<String,Object>b){Identity.role("ADMIN");long actor=Identity.id();return db.tx(()->{Map<String,Object> p=db.need("SELECT * FROM tb_ticket_product WHERE id=? FOR UPDATE",id);boolean disabled="INACTIVE".equals(text(b,"status"));
        if(disabled){db.update("UPDATE tb_ticket_product SET status='INACTIVE' WHERE id=?",id);for(Map<String,Object> s:db.rows("SELECT id FROM tb_ticket_sku WHERE product_id=? AND state IN('READY','ON_SALE','PAUSED')",id)){db.update("UPDATE tb_ticket_sku SET control_state='PAUSING' WHERE id=?",s.get("id"));writer.outbox("pause:"+text(s,"id")+":"+UUID.randomUUID(),text(s,"id"),"PAUSE",map("skuId",text(s,"id")));}}
        else{if(db.count("SELECT COUNT(*) FROM tb_ticket_sku WHERE product_id=? AND state<>'DRAFT'",id)>0)throw new ApiFault(409,"PRODUCT_FROZEN","已有发布批次，票种文案冻结；请新建票种");db.update("UPDATE tb_ticket_product SET name=?,description=? WHERE id=?",required(b,"name",100),required(b,"description",10000),id);}
        invalidateAttraction(number(p,"attraction_id"));db.audit(actor,disabled?"DISABLE_PRODUCT":"EDIT_PRODUCT",Long.toString(id),text(p,"status"),disabled?"INACTIVE":"EDITED");return map("productId",Long.toString(id),"message",disabled?"已停用，关联批次暂停处理中":"票种已更新");});}
    @GetMapping("/ticket-skus") public Object skus(@RequestParam(defaultValue="1") int page){Identity.role("ADMIN");if(page<1||page>100000)throw new ApiFault(400,"INVALID_PARAMETER","页码不正确");return map("items",stringIds(db.rows("SELECT s.*,p.name AS product_name,a.name AS attraction_name FROM tb_ticket_sku s JOIN tb_ticket_product p ON p.id=s.product_id JOIN tb_shop a ON a.id=p.attraction_id ORDER BY s.visit_date,s.id LIMIT 100 OFFSET ?",(page-1)*100)),"total",db.count("SELECT COUNT(*) FROM tb_ticket_sku"));}
    @PostMapping("/ticket-skus") public Object sku(@RequestBody Map<String,Object> b){Identity.role("ADMIN");long product=positive(b,"productId"),actor=Identity.id();long priceValue;try{priceValue=number(b,"priceCent");}catch(Exception e){throw new ApiFault(400,"INVALID_PARAMETER","售价必须是整数分");}long stockValue=positive(b,"totalStock");if(priceValue<0||priceValue>10000000||stockValue>1000000)throw new ApiFault(400,"INVALID_PARAMETER","价格或库存超出范围");int price=(int)priceValue,stock=(int)stockValue;
        LocalDate date;try{date=LocalDate.parse(required(b,"visitDate",10));}catch(Exception e){throw new ApiFault(400,"INVALID_DATE","使用日期不正确");}
        long from=time(b.get("validFrom")),until=time(b.get("validUntil")),start=time(b.get("saleStart")),end=time(b.get("saleEnd"));long day=date.atStartOfDay(ZONE).toInstant().toEpochMilli(),next=date.plusDays(1).atStartOfDay(ZONE).toInstant().toEpochMilli();
        if(from<day||until>next||from>=until||start>=end||end>until-900000||until<=System.currentTimeMillis())throw new ApiFault(400,"INVALID_WINDOW","日期与入园时间不一致，售卖须在入园结束前15分钟截止");
        return db.tx(()->{db.need("SELECT id FROM tb_ticket_product WHERE id=? AND status='ACTIVE'",product);if(db.count("SELECT COUNT(*) FROM tb_ticket_sku WHERE product_id=? AND visit_date=?",product,date.toString())>0)throw new ApiFault(409,"SKU_EXISTS","该票种使用日期已配置，不允许重建");long id=inserted("INSERT INTO tb_ticket_sku(product_id,visit_date,valid_from,valid_until,sale_start,sale_end,price_cent,total_stock,available_stock,epoch) VALUES(?,?,?,?,?,?,?,?,?,?)",product,date.toString(),from,until,start,end,price,stock,stock,UUID.randomUUID().toString());db.audit(actor,"CREATE_SKU",Long.toString(id),"","DRAFT");return map("skuId",Long.toString(id));});}
    @PostMapping("/ticket-skus/{id}/{action}") public Object control(@PathVariable long id,@PathVariable String action){Identity.role("ADMIN");long actor=Identity.id();RLock lock=redisson.getLock("jy:v1:sku-control:"+id);lock.lock();try{
        Map<String,Object> s=db.need("SELECT s.*,p.attraction_id,p.status AS product_status,a.published FROM tb_ticket_sku s JOIN tb_ticket_product p ON p.id=s.product_id JOIN tb_attraction_profile a ON a.shop_id=p.attraction_id WHERE s.id=?",id);String state=text(s,"state");
        if(!text(s,"control_state").isEmpty())throw new ApiFault(409,"CONTROL_PENDING","批次有未完成恢复或暂停，请先核对");
        if("warmup".equals(action)){
            if(!Arrays.asList("DRAFT","READY").contains(state))throw new ApiFault(409,"INVALID_STATE","只允许预热草稿或就绪批次");
            if(db.count("SELECT COUNT(*) FROM tb_ticket_request_result WHERE sku_id=?",id)>0)throw new ApiFault(409,"HAS_TRADES","有交易证据，禁止覆盖库存");
            boolean seen=db.count("SELECT COUNT(*) FROM tb_ticket_warmup WHERE sku_id=?",id)>0;
            if(seen&&ops.field("meta:"+id).isEmpty())throw new ApiFault(409,"RECOVERY_REQUIRED","曾经预热的批次元数据丢失，必须人工对账，禁止从数据库回填");
            db.update("INSERT IGNORE INTO tb_ticket_warmup(sku_id,epoch,created_at) VALUES(?,?,?)",id,s.get("epoch"),System.currentTimeMillis());
            String meta=json(map("configVersion",text(s,"config_version"),"epoch",s.get("epoch"),"saleStart",text(s,"sale_start"),"saleEnd",text(s,"sale_end"),"validUntil",text(s,"valid_until"),"totalStock",text(s,"total_stock")));
            Long n=ops.redis.execute(warmup,Collections.singletonList(RedisOps.STATE),Long.toString(id),meta,text(s,"available_stock"));if(n==null||n<0)throw new ApiFault(409,"WARMUP_CONFLICT","元数据冲突，禁止覆盖");
            return transition(id,actor,state,"READY");
        }
        if("publish".equals(action)||"resume".equals(action)){
            if(!Arrays.asList("READY","PAUSED","ON_SALE").contains(state)||number(s,"published")!=1||!"ACTIVE".equals(text(s,"product_status")))throw new ApiFault(409,"INVALID_STATE","景点未发布或批次未就绪");
            if(ops.field("meta:"+id).isEmpty()||ops.field("stock:"+id).isEmpty()||!ops.field("fence:"+id).isEmpty())throw new ApiFault(409,"RECOVERY_REQUIRED","元数据缺失或仍有恢复屏障，禁止重预热");
            // DB first on open; partial failure remains closed in Redis until the explicit retry.
            Object r=transition(id,actor,state,"ON_SALE");ops.redis.opsForHash().put(RedisOps.STATE,"sale:"+id,"ON_SALE");return r;
        }
        if("pause".equals(action)){
            if(!Arrays.asList("ON_SALE","PAUSED").contains(state))throw new ApiFault(409,"INVALID_STATE","当前批次不可暂停");
            // Durable intent precedes network call. Worker closes Redis before final management state.
            db.tx(()->{db.update("UPDATE tb_ticket_sku SET control_state='PAUSING' WHERE id=?",id);writer.outbox("pause:"+id+":"+UUID.randomUUID(),Long.toString(id),"PAUSE",map("skuId",Long.toString(id)));db.audit(actor,"PAUSE",Long.toString(id),state,"PAUSING");return null;});
            pipeline.dispatchDb();return map("state","PAUSING","message","暂停已提交，等待确认关闭受理");
        }
        if("end".equals(action)) {ops.redis.opsForHash().put(RedisOps.STATE,"sale:"+id,"ENDED");return transition(id,actor,state,"ENDED");}
        if("archive".equals(action)&&"ENDED".equals(state)&&System.currentTimeMillis()>=number(s,"valid_until")&&db.count("SELECT COUNT(*) FROM tb_ticket_outbox WHERE aggregate_id IN(SELECT CAST(id AS CHAR) FROM tb_ticket_order WHERE sku_id=?) AND state='PENDING'",id)==0&&ops.field("fence:"+id).isEmpty())return transition(id,actor,state,"ARCHIVED");
        throw new ApiFault(409,"INVALID_STATE","不支持该状态操作");
    }finally{if(lock.isHeldByCurrentThread())lock.unlock();}}
    Object transition(long id,long actor,String before,String after){return db.tx(()->{db.update("UPDATE tb_ticket_sku SET state=? WHERE id=?",after,id);db.audit(actor,"SKU_"+after,Long.toString(id),before,after);return map("skuId",Long.toString(id),"state",after);});}
    @GetMapping("/failures") public Object failures(){Identity.role("ADMIN");return map("items",stringIds(db.rows("SELECT id,event_id,order_id,sku_id,error_code,reason,attempts,state,first_at,last_at FROM tb_ticket_failure ORDER BY id DESC LIMIT 200")));}
    @PostMapping("/failures/{id}/{action}") public Object resolve(@PathVariable long id,@PathVariable String action,@RequestBody Map<String,Object> b){Identity.role("ADMIN");Map<String,Object> f=db.need("SELECT * FROM tb_ticket_failure WHERE id=?",id);if("retry".equals(action))pipeline.retry(f,Identity.id());else if("reject".equals(action)){writer.reject(object(text(f,"original_payload")),Identity.id(),required(b,"reason",200));db.update("UPDATE tb_ticket_failure SET state='REJECTED' WHERE id=?",id);}else throw new ApiFault(400,"INVALID_ACTION","处置动作不正确");return map("handled",true);}
    @GetMapping("/audit") public Object audit(){Identity.role("ADMIN");return map("items",stringIds(db.rows("SELECT * FROM tb_operation_audit ORDER BY id DESC LIMIT 200")));}
    @GetMapping("/reconciliation") public Object reconcile(){Identity.role("ADMIN");List<Map<String,Object>> out=new ArrayList<>();long now=System.currentTimeMillis();int watch=0,alarm=0;
        Map<String,String> requests=new LinkedHashMap<>();int fences=0;long oldest=now;
        try(org.springframework.data.redis.core.Cursor<Map.Entry<Object,Object>> cursor=ops.redis.opsForHash().scan(RedisOps.STATE,org.springframework.data.redis.core.ScanOptions.scanOptions().match("req:*").count(1000).build())){while(cursor.hasNext()){Map.Entry<Object,Object> e=cursor.next();if(!e.getValue().toString().isEmpty()){Map<String,Object> ev=object(e.getValue().toString());if(ev.containsKey("acceptedAt")&&!"REJECTED".equals(text(ev,"result")))requests.put(text(ev,"orderId"),e.getValue().toString());}}}
        try(org.springframework.data.redis.core.Cursor<Map.Entry<Object,Object>> cursor=ops.redis.opsForHash().scan(RedisOps.STATE,org.springframework.data.redis.core.ScanOptions.scanOptions().match("fence:*").count(1000).build())){while(cursor.hasNext())if(!cursor.next().getValue().toString().isEmpty())fences++;}
        Set<String> settled=new HashSet<>();List<String> requestIds=new ArrayList<>(requests.keySet());for(int offset=0;offset<requestIds.size();offset+=500){Object[] ids=requestIds.subList(offset,Math.min(requestIds.size(),offset+500)).toArray();for(Map<String,Object> r:db.rows("SELECT order_id FROM tb_ticket_request_result WHERE result IN('CREATED','REJECTED') AND order_id IN ("+TicketWriter.marks(ids.length)+")",ids))settled.add(text(r,"order_id"));}
        Map<String,Integer> pending=new HashMap<>();for(Map.Entry<String,String> entry:requests.entrySet())if(!settled.contains(entry.getKey())){Map<String,Object> ev=object(entry.getValue());pending.merge(text(ev,"skuId"),1,Integer::sum);long age=now-number(ev,"acceptedAt");oldest=Math.min(oldest,number(ev,"acceptedAt"));if(age>60000)watch++;if(age>300000)alarm++;}
        Map<String,Long> releases=new HashMap<>();for(Map<String,Object> r:db.rows("SELECT JSON_UNQUOTE(JSON_EXTRACT(payload,'$.skuId')) AS sku,COUNT(*) AS n FROM tb_ticket_outbox WHERE event_type='RELEASE' AND state='PENDING' GROUP BY sku"))releases.put(text(r,"sku"),number(r,"n"));
        Map<String,Long> failures=new HashMap<>();for(Map<String,Object> r:db.rows("SELECT JSON_UNQUOTE(JSON_EXTRACT(original_payload,'$.skuId')) AS sku,COUNT(*) AS n FROM tb_ticket_failure WHERE state='OPEN' AND JSON_VALID(original_payload) GROUP BY sku"))failures.put(text(r,"sku"),number(r,"n"));
        List<Map<String,Object>> skus=db.rows("SELECT s.*,p.name,a.name AS attraction_name,COALESCE(c.n_PENDING_PAYMENT,0) AS n_PENDING_PAYMENT,COALESCE(c.n_PAID,0) AS n_PAID,COALESCE(c.n_USED,0) AS n_USED,COALESCE(c.n_EXPIRED,0) AS n_EXPIRED,COALESCE(c.n_CLOSED,0) AS n_CLOSED FROM tb_ticket_sku s JOIN tb_ticket_product p ON p.id=s.product_id JOIN tb_shop a ON a.id=p.attraction_id LEFT JOIN (SELECT sku_id,SUM(state='PENDING_PAYMENT') AS n_PENDING_PAYMENT,SUM(state='PAID') AS n_PAID,SUM(state='USED') AS n_USED,SUM(state='EXPIRED') AS n_EXPIRED,SUM(state='CLOSED') AS n_CLOSED FROM tb_ticket_order GROUP BY sku_id) c ON c.sku_id=s.id ORDER BY s.id");List<Object> stockKeys=new ArrayList<>();for(Map<String,Object> sku:skus)stockKeys.add("stock:"+text(sku,"id"));List<Object> stocks=stockKeys.isEmpty()?Collections.emptyList():ops.redis.opsForHash().multiGet(RedisOps.STATE,stockKeys);
        for(int i=0;i<skus.size();i++){Map<String,Object> s=skus.get(i);String sid=text(s,"id");
            Map<String,Object> r=map("skuId",sid,"name",s.get("attraction_name"),"visitDate",text(s,"visit_date"),"state",s.get("state"),"controlState",s.get("control_state"),"total",s.get("total_stock"),"dbAvailable",s.get("available_stock"),"redisAvailable",stocks.get(i),"processing",pending.getOrDefault(sid,0));long occupied=0;
            for(String state:Arrays.asList("PENDING_PAYMENT","PAID","USED","EXPIRED","CLOSED")){long count=number(s,"n_"+state);r.put(state,count);if(!"CLOSED".equals(state))occupied+=count;}
            r.put("dbInvariant",number(s,"total_stock")==number(s,"available_stock")+occupied);r.put("releasePending",releases.getOrDefault(sid,0L));r.put("failures",failures.getOrDefault(sid,0L));out.add(r);
        }
        return map("items",out,"sampleAt",instant(now),"kafka",ops.redis.opsForValue().get(RedisOps.HEALTH),"redisOutbox",ops.redis.opsForStream().size(RedisOps.STREAM),"dbOutbox",db.count("SELECT COUNT(*) FROM tb_ticket_outbox WHERE state='PENDING'"),"failures",db.count("SELECT COUNT(*) FROM tb_ticket_failure WHERE state='OPEN'"),"recoveryFences",fences,"oldestProcessingMs",now-oldest,"attention",watch,"alarms",alarm,"lateReleases",db.count("SELECT COUNT(*) FROM tb_ticket_outbox WHERE event_type='RELEASE' AND state='PENDING' AND created_at<?",now-30000),"lateCloses",db.count("SELECT COUNT(*) FROM tb_ticket_order WHERE state='PENDING_PAYMENT' AND pay_deadline<?",now-30000));
    }
    static List<Map<String,Object>> stringIds(List<Map<String,Object>> rows){for(Map<String,Object> r:rows)for(String k:new ArrayList<>(r.keySet()))if(k.equals("id")||k.endsWith("_id")||k.equals("config_version"))if(r.get(k)!=null)r.put(k,r.get(k).toString());return rows;}
}
